#include <stdio.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

int getResult(int nums_len, const int nums[], int n) {
    // 初始时，左边选择0个，因此左边选择的香蕉数为 0
    int leftSum = 0;

    // 初始时，右边选择n个，因此右边选择的香蕉数为 nums[len-n] ~ nums[len - 1] 这个n个元素之和
    int rightSum = 0;
    for (int i = nums_len - n; i < nums_len; i++) {
        rightSum += nums[i];
    }

    // 如果选择数n == len，即全选，此时直接返回初始rightSum
    if (nums_len == n) {
        return rightSum;
    }

    // 如果不是全选
    // sum记录当前选择结果
    int sum = leftSum + rightSum;
    // ans记录所有选择结果中最大的
    int ans = sum;

    // l指向左边将要获得的，即左边获得一个
    int l = 0;
    // r指向右边将要失去的，即右边失去一个
    int r = nums_len - n;

    while (l < n) {
        sum += nums[l++] - nums[r++];
        ans = MAX(ans, sum);
    }

    return ans;
}

int main() {
    int nums_len;
    scanf("%d", &nums_len);

    int nums[nums_len];
    for (int i = 0; i < nums_len; i++) {
        scanf("%d", &nums[i]);
    }

    int n;
    scanf("%d", &n);

    printf("%d\n", getResult(nums_len, nums, n));

    return 0;
}
